import{_ as e,c as a,o as r,ag as o}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"SUAS Breakdown","description":"","frontmatter":{"title":"SUAS Breakdown"},"headers":[],"relativePath":"general/suas-breakdown.md","filePath":"general/suas-breakdown.md","lastUpdated":null}'),n={name:"general/suas-breakdown.md"};function i(s,t,d,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="suas-breakdown" tabindex="-1">SUAS Breakdown <a class="header-anchor" href="#suas-breakdown" aria-label="Permalink to &quot;SUAS Breakdown&quot;">​</a></h1><ol><li>small Unmanned Aerial Systems An unmanned aerial vehicle (UAV) or unmanned aircraft system (UAS), commonly known as a drone, is an aircraft with no human pilot, crew, or passengers onboard, but rather is controlled remotely or is autonomous.</li></ol><h3 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h3><ul><li><p><strong>Unmanned aircraft</strong>: The term &quot;unmanned aircraft&quot; means an aircraft that is operated without the possibility of direct human intervention from within or on the aircraft.</p></li><li><p><strong>Unmanned aircraft system</strong>: The term &quot;unmanned aircraft system&quot; means an unmanned aircraft and associated elements (including communication links and the components that control the unmanned aircraft) that are required for the operator to operate safely and efficiently in the national airspace system.</p></li><li><p><strong>Small unmanned aircraft</strong>: The term &quot;small unmanned aircraft&quot; means an unmanned aircraft weighing less than 55 pounds, including the weight of anything attached to or carried by the aircraft.</p></li><li><p><strong>ESAD</strong>: Electronic Safe and Arm Device - a critical safety component used in an ordnance system, not specific to UAS. Provides electronic control of arming and firing functions with multiple safety interlocks.</p></li><li><p><strong>ESAF</strong>: Electronic Safe Arming and Fire - legacy term more commonly used in UK contexts than ESAD. Both ESAD and ESAF are fundamental safety features in an ordnance system, ensuring proper arming sequences and preventing accidental detonation.</p></li><li><p><strong>ELRS</strong>: ExpressLRS – a low-latency, long-range radio protocol that transmits control inputs and optionally telemetry (like battery voltage, GPS, etc.)</p></li><li><p><strong>LRS</strong>: Long Range System used to maintain command &amp; control links over 10–30+ km</p></li><li><p><strong>ESCs</strong>: Electronic Speed Controllers</p></li><li><p><strong>FPV</strong>: First Person View</p></li><li><p><strong>IMU</strong>: Inertial Measurement Unit</p></li><li><p><strong>GPS</strong>: Global Positioning System</p></li><li><p><strong>GNSS</strong>: Global Navigation Satellite System</p></li><li><p><strong>VTX</strong>: Video Transmitter</p></li><li><p><strong>RX</strong>: Receiver</p></li><li><p><strong>FC</strong>: Flight Controller</p></li><li><p><strong>OSD</strong>: On-Screen Display</p></li><li><p><strong>SBS</strong>: Soldier Borne Sensor</p></li><li><p><strong>GCS</strong>: Ground Control Station</p></li><li><p><strong>Pixel Lock</strong>: A computer-vision-based target-tracking mode found in advanced FPV and autonomous small UAS. Once the operator designates a subject (person, vehicle, structure, etc.), the onboard AI locks onto the target’s pixel representation in the video feed, continuously tracking it—even if GPS or radio communications are lost.</p></li></ul><h3 id="uas-groups" tabindex="-1">UAS Groups <a class="header-anchor" href="#uas-groups" aria-label="Permalink to &quot;UAS Groups&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Group</th><th>Weight</th><th>Alt</th><th>Speed</th><th>DoD Label</th><th>Common Roles</th><th>Examples</th></tr></thead><tbody><tr><td>microUAS/SBS</td><td>&lt; 0.55 lb</td><td>&lt; 100 ft AGL</td><td>&lt; 30 kt</td><td>Army SBS</td><td>Individual soldier ISR, pocket/nano UAS</td><td>Black Hornet</td></tr><tr><td>Group 1</td><td>0 – 20 lb</td><td>&lt; 1,200 ft AGL</td><td>&lt; 100 kt</td><td>Small sUAS</td><td>Platoon ISR, FPV-strike, point recon</td><td>RQ-28A SRR, DJI Mavic 3</td></tr><tr><td>Group 2</td><td>21 – 55 lb</td><td>&lt; 3,500 ft AGL</td><td>&lt; 250 kt</td><td>Small sUAS</td><td>Company/Bn ISR, light kinetic, precision resupply</td><td>RQ-11 Raven, RQ-20 Puma, ScanEagle</td></tr><tr><td>Group 3</td><td>56 – 1,320 lb</td><td>&lt; 18,000 ft MSL</td><td>&lt; 250 kt</td><td>Large sUAS</td><td>Bn/brigade ISR, hybrid-VTOL cargo, comms relay</td><td>YRQ-30A, RQ-7 Shadow, V-BAT</td></tr><tr><td>Group 4</td><td>&gt; 1,320 lb</td><td>&lt; 18,000 ft MSL</td><td>Any</td><td>Tactical UAS</td><td>Armed ISR, EW, extended-range strike</td><td>MQ-1C Gray Eagle, MQ-8B Fire Scout</td></tr><tr><td>Group 5</td><td>&gt; 1,320 lb</td><td>&gt; 18,000 ft MSL</td><td>Any</td><td>Strategic UAS</td><td>HALE ISR/strike, deep-strike, maritime patrol</td><td>MQ-9 Reaper, RQ-4 Global Hawk</td></tr></tbody></table><ol><li>sUAS Components</li></ol><h3 id="suas-—-core-flight-hardware-must-have" tabindex="-1">sUAS — Core Flight Hardware (Must Have) <a class="header-anchor" href="#suas-—-core-flight-hardware-must-have" aria-label="Permalink to &quot;sUAS — Core Flight Hardware (Must Have)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sub-system</th><th>Key parts</th><th>Why it&#39;s indispensable</th></tr></thead><tbody><tr><td>Airframe / Structure</td><td>Frame plates or fuselage; arms/booms; landing skids/bumper</td><td>Holds everything together and sets thrust line / CG</td></tr><tr><td>Propulsion</td><td>Brushless motors (2205–2807 KV); matching propellers; ESCs (20–60 A, BLHeli-32)</td><td>Converts electrical energy into thrust and steering authority</td></tr><tr><td>Energy</td><td>Li-Po/Li-ion battery pack (4 S–6 S) / hybrid or fuel engine</td><td>Powers all onboard systems; sets endurance ceiling</td></tr><tr><td>Flight-control brain</td><td>IMU-equipped flight controller; GPS/GNSS module; barometer; magnetometer</td><td>Runs autopilot firmware; fuses sensor data; closes control loops</td></tr><tr><td>C2 / Telemetry</td><td>RC receiver (ELRS, Crossfire, DJI OcuSync); datalink radio; antennas</td><td>Operator commands in, health &amp; video out</td></tr><tr><td>Power distribution</td><td>XT60/XT90 lead; silicone-insulated loom; power-distribution board</td><td>Safely routes high-current battery output to ESCs &amp; avionics</td></tr><tr><td>Optional</td><td>FPV / EO-IR camera; video TX; companion computer; payload mount</td><td>Adds ISR or strike capability</td></tr></tbody></table><h3 id="fielded-configurations-ukraine-2023–25" tabindex="-1">Fielded Configurations (Ukraine 2023–25) <a class="header-anchor" href="#fielded-configurations-ukraine-2023–25" aria-label="Permalink to &quot;Fielded Configurations (Ukraine 2023–25)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>COTS Quad (DJI Mavic 3)</th><th>FPV Kamikaze (DIY 5″–7″)</th><th>Stick-frame Improvised</th></tr></thead><tbody><tr><td>Frame</td><td>Injection-moulded, folding arms</td><td>5–7″ carbon X-frame</td><td>Pine / bamboo sticks; zip-ties</td></tr><tr><td>Motors</td><td>Integrated in arm</td><td>2306 / 2307 / 2807 6S outrunners</td><td>Cheap 2306 1900 KV sets</td></tr><tr><td>Propellers</td><td>Folding 9–9.4″ 2-blade</td><td>5–7″ tri-blade poly-carbonate</td><td>Any 5″ nylon/carbon pair</td></tr><tr><td>ESCs</td><td>Integrated 4-in-1</td><td>45–60 A BLHeli-32 (singles or 4-in-1)</td><td>Same, heat-shrunk to stick arm</td></tr><tr><td>Battery</td><td>Smart 4S 5000 mAh Li-Po (≈77 Wh)</td><td>6S 1300–1800 mAh Li-Po</td><td>Recycled 6S or parallel tool packs</td></tr><tr><td>FC firmware</td><td>DJI proprietary</td><td>Betaflight / iNav or ArduPilot</td><td>Same on low-cost F722 boards</td></tr><tr><td>RC / Video</td><td>DJI OcuSync 2.4 / 5.8 GHz</td><td>ExpressLRS RX + 5.8 GHz 1W VTX</td><td>Crossfire or ELRS; VTX taped on</td></tr><tr><td>Typical payload</td><td>4K gimbal cam; grenade drop-mod</td><td>3D-printed nose with PG-7V or 40mm HEDP; ESAD PCB</td><td>Stick spear, thermite charge</td></tr></tbody></table><h3 id="why-each-piece-matters" tabindex="-1">Why Each Piece Matters <a class="header-anchor" href="#why-each-piece-matters" aria-label="Permalink to &quot;Why Each Piece Matters&quot;">​</a></h3><ul><li><p><strong>Propellers</strong> – diameter + pitch must suit motor KV &amp; voltage; wrong combo causes brown-outs or stalls.</p></li><li><p><strong>Motors</strong> – 2306/07 outrunners deliver ≈1 kg thrust each on 6 S × 5″ props (enough for 0.5 kg warhead 15–20 km).</p></li><li><p><strong>ESCs</strong> – BLHeli-32 flashed to 48 kHz reduces acoustic signature.</p></li><li><p><strong>Frame material</strong> – carbon = rigid &amp; low-RF; wood sticks are cheap, radar-transparent, disposable.</p></li><li><p><strong>Battery chemistry</strong> – 6 S packs give power head-room for high-g dive-attacks.</p></li><li><p><strong>ELRS / Crossfire</strong> – sub-gram RXs, 10–20 km L-o-S, frequency-hopping anti-jam.</p></li><li><p><strong>ESAD add-ons</strong> – simple MOSFET safe/arm PCB triggered by spare FC output; dual-command logic prevents accidental detonation.</p></li></ul><h3 id="minimal-shopping-list" tabindex="-1">Minimal Shopping List <a class="header-anchor" href="#minimal-shopping-list" aria-label="Permalink to &quot;Minimal Shopping List&quot;">​</a></h3><h2 id="four-brushless-motors-matching-props" tabindex="-1">Four brushless motors + matching props <a class="header-anchor" href="#four-brushless-motors-matching-props" aria-label="Permalink to &quot;Four brushless motors + matching props&quot;">​</a></h2><h2 id="four-escs-or-one-4-in-1-board" tabindex="-1">Four ESCs (or one 4-in-1 board) <a class="header-anchor" href="#four-escs-or-one-4-in-1-board" aria-label="Permalink to &quot;Four ESCs (or one 4-in-1 board)&quot;">​</a></h2><h2 id="li-po-battery-xt60-lead" tabindex="-1">Li-Po battery + XT60 lead <a class="header-anchor" href="#li-po-battery-xt60-lead" aria-label="Permalink to &quot;Li-Po battery + XT60 lead&quot;">​</a></h2><h2 id="basic-frame-sticks-carbon-or-3-d-printed" tabindex="-1">Basic frame (sticks, carbon, or 3-D-printed) <a class="header-anchor" href="#basic-frame-sticks-carbon-or-3-d-printed" aria-label="Permalink to &quot;Basic frame (sticks, carbon, or 3-D-printed)&quot;">​</a></h2><h2 id="flight-controller-stack-w-imu-gps-puck" tabindex="-1">Flight-controller stack w/ IMU + GPS puck <a class="header-anchor" href="#flight-controller-stack-w-imu-gps-puck" aria-label="Permalink to &quot;Flight-controller stack w/ IMU + GPS puck&quot;">​</a></h2><h2 id="rc-receiver-antennas" tabindex="-1">RC receiver &amp; antennas <a class="header-anchor" href="#rc-receiver-antennas" aria-label="Permalink to &quot;RC receiver &amp; antennas&quot;">​</a></h2><h2 id="power-distribution-harness-wiring" tabindex="-1">Power-distribution harness &amp; wiring <a class="header-anchor" href="#power-distribution-harness-wiring" aria-label="Permalink to &quot;Power-distribution harness &amp; wiring&quot;">​</a></h2><ol><li><em>Optional:</em> FPV camera + VTX, payload mount, ESAD module if carrying explosives</li></ol><h3 id="roles-involving-suas" tabindex="-1">Roles Involving sUAS <a class="header-anchor" href="#roles-involving-suas" aria-label="Permalink to &quot;Roles Involving sUAS&quot;">​</a></h3><p>;Pilot / Operator : Directly controls the aircraft (manual, semi-autonomous, or autonomous modes) and executes the mission profile. ;Payload / Sensor Operator : Manages cameras, ISR sensors, or munitions; responsible for target acquisition, release, or data capture. ;Mission Planner : Builds flight plans, waypoints, geofences, and contingency procedures; uploads mission data to the FC/GCS. ;Launch &amp; Recovery Crew : Handles physical launch methods (hand-launch, bungee, catapult, VTOL spool-up) and safe recovery or retrieval. ;Maintenance Technician : Performs pre-flight checks, field repairs, firmware updates, battery health monitoring, and post-flight inspections. ;ESAD Armorer : Implements Electronic Safe-and-Arm procedures for any explosive payload; verifies dual-command logic before arming. ;Data Analyst / Intelligence Cell : Processes collected imagery/telemetry into actionable intelligence or battle-damage assessments. ;Instructor / Standardization Pilot : Trains crews, maintains SOPs, and ensures compliance with regulatory and tactical standards.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Systems]</p>',26)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
